import "server-only";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { PlateSource, PlateSources } from "./plate-types";
import { PLATE_IDS, PLATES, type PlateId, type SceneImage, type StillName } from "./world.config";

export type { PlateSource, PlateSources } from "./plate-types";

// All media here is generated by `python design-refs/scripts/hfa_media.py all`
// (folder contract, Master Prompt v4 step 0). Nothing is hand-made or upscaled.
const PUBLIC = join(process.cwd(), "public");

function readManifest(id: PlateId): PlateSource | null {
  const file = join(PUBLIC, "assets/plates", id, "manifest.json");
  if (!existsSync(file)) return null;
  try {
    const m = JSON.parse(readFileSync(file, "utf8"));
    if (!Number.isInteger(m.frames) || m.frames < 1 || !m.width || !m.height) return null;
    return {
      id,
      base: `/assets/plates/${id}`,
      frames: m.frames,
      width: m.width,
      height: m.height,
      pattern: typeof m.pattern === "string" ? m.pattern : "f_%03d.webp",
      bytes: Number(m.bytes) || 0,
    };
  } catch {
    return null;
  }
}

/** Which plates exist on disk. Missing ones fall back per world.config (never block the page). */
export function getPlateSources(): PlateSources {
  const out: PlateSources = {};
  for (const id of PLATE_IDS) {
    const src = readManifest(id);
    if (src) out[id] = src;
  }
  return out;
}

/** URL of a plate's poster/last frame, following the fallback chain; null = flat mood colour. */
export function stillUrl(sources: PlateSources, plate: PlateId, frame: "poster" | "last"): string | null {
  const src = sources[plate];
  if (src) return `${src.base}/${frame}.webp`;
  const fb = PLATES[plate].fallback;
  return fb ? stillUrl(sources, fb.plate, fb.frame) : null;
}

/** A named page still (public/assets/stills/<name>.webp), if it was generated. */
export function namedStillUrl(name: StillName): string | null {
  return existsSync(join(PUBLIC, "assets/stills", `${name}.webp`)) ? `/assets/stills/${name}.webp` : null;
}

/** Resolve a route's scene image: its own named still first, then the plate frame, then null (mood colour). */
export function sceneImageUrl(sources: PlateSources, scene: SceneImage): string | null {
  return (scene.still && namedStillUrl(scene.still)) || stillUrl(sources, scene.plate, scene.frame);
}
